// Validate and normalise the tool arguments before spending an embedding call.
//
// The caller is an LLM, so arguments arrive as whatever the model decided to
// emit: missing fields, wrong types, numbers as strings. Failing here costs
// nothing; failing after the Gemini call costs quota and latency.
//
// This node is the single place that reads the container environment. HTTP
// nodes can reach $env at runtime, but their expression preview cannot, which
// makes them awkward to debug and easy to break silently. Reading everything
// here keeps configuration in one auditable place.
//
// A Code node has a single output, so errors are returned as a normal item
// carrying `ok: false`. Downstream nodes branch on that field via If.

const ALLOWED_ENTITY_TYPES = ['product', 'category'];
const MAX_QUERY_LENGTH = 200;
const DEFAULT_LIMIT = 3;
const MAX_LIMIT = 10;

const input = $input.first().json ?? {};

const rawQuery = typeof input.query === 'string' ? input.query.trim() : '';
const rawEntityType =
  typeof input.entity_type === 'string' ? input.entity_type.trim().toLowerCase() : '';

const errors = [];

if (!rawQuery) {
  errors.push('query is required and must be a non-empty string');
} else if (rawQuery.length > MAX_QUERY_LENGTH) {
  errors.push(`query must be at most ${MAX_QUERY_LENGTH} characters`);
}

if (!ALLOWED_ENTITY_TYPES.includes(rawEntityType)) {
  errors.push(`entity_type must be one of: ${ALLOWED_ENTITY_TYPES.join(', ')}`);
}

// Models frequently emit numbers as strings, so coerce before validating.
let limit = DEFAULT_LIMIT;
if (input.limit !== undefined && input.limit !== null && input.limit !== '') {
  const parsed = Number(input.limit);
  if (!Number.isInteger(parsed) || parsed < 1 || parsed > MAX_LIMIT) {
    errors.push(`limit must be an integer between 1 and ${MAX_LIMIT}`);
  } else {
    limit = parsed;
  }
}

const model = $env.EMBEDDING_MODEL;
const dimension = Number($env.EMBEDDING_DIM);
const qdrantUrl = ($env.QDRANT_URL || '').replace(/\/+$/, '');
const collection = $env.QDRANT_COLLECTION;
const apiKey = $env.GEMINI_API_KEY;

if (!model) errors.push('EMBEDDING_MODEL is not set in the container environment');
if (!Number.isInteger(dimension) || dimension < 1) {
  errors.push('EMBEDDING_DIM is not a positive integer');
}
if (!qdrantUrl) errors.push('QDRANT_URL is not set in the container environment');
if (!collection) errors.push('QDRANT_COLLECTION is not set in the container environment');
if (!apiKey) errors.push('GEMINI_API_KEY is not set in the container environment');

if (errors.length > 0) {
  return [
    {
      json: {
        ok: false,
        status: 'invalid_input',
        errors,
        message: `Invalid tool arguments: ${errors.join('; ')}`,
      },
    },
  ];
}

return [
  {
    json: {
      ok: true,
      query: rawQuery,
      entity_type: rawEntityType,
      limit,
      model,
      dimension,
      embed_url: `https://generativelanguage.googleapis.com/v1beta/${model}:embedContent`,
      search_url: `${qdrantUrl}/collections/${collection}/points/query`,
      collection,
      api_key: apiKey,
    },
  },
];

// Turn raw Qdrant hits into a decision the agent can act on.
//
// Thresholds are measured, not guessed. On the verification suite (10.5):
//   correct hits scored 0.645 - 0.739
//   nonsense queries scored 0.545 - 0.550
// The confidence floor sits in the middle of that gap with equal margin on
// both sides; at 31 points the sample is too small to justify hugging either
// edge.
//
// The ambiguity margin exists because a filtered search always returns
// something. "Электроника" beats the runner-up by only 0.030, so a confident
// top hit is not the same as an unambiguous one. Below the margin the agent
// must ask rather than assume - which is exactly what the inline-button
// confirmation in step 13 is for.
//
// Deciding here rather than in the prompt is deliberate: a model asked to
// interpret raw scores tends to take the first result regardless.

const MIN_SCORE = 0.6;
const MIN_MARGIN = 0.05;

const context = $('validate-input').first().json;

// The validator short-circuits on bad arguments; pass its verdict through.
if (context.ok === false) {
  return [{ json: { status: context.status, message: context.message, errors: context.errors } }];
}

const response = $input.first().json ?? {};
const points = response?.result?.points ?? [];

const candidates = points.map((point) => {
  const payload = point.payload ?? {};
  return {
    entity_type: payload.entity_type,
    entity_id: payload.entity_id,
    name: payload.name,
    slug: payload.slug,
    sku: payload.sku,
    price: payload.price,
    product_type: payload.product_type,
    stock_status: payload.stock_status,
    category_ids: payload.category_ids ?? [],
    product_count: payload.product_count,
    score: Number(point.score.toFixed(4)),
  };
});

const base = {
  query: context.query,
  entity_type: context.entity_type,
  thresholds: { min_score: MIN_SCORE, min_margin: MIN_MARGIN },
};

if (candidates.length === 0) {
  return [
    {
      json: {
        ...base,
        status: 'not_found',
        match: null,
        candidates: [],
        message: `No ${context.entity_type} matches "${context.query}".`,
      },
    },
  ];
}

const top = candidates[0];
const runnerUp = candidates[1] ?? null;
const margin = runnerUp ? Number((top.score - runnerUp.score).toFixed(4)) : null;

if (top.score < MIN_SCORE) {
  return [
    {
      json: {
        ...base,
        status: 'not_found',
        match: null,
        candidates,
        best_score: top.score,
        message:
          `No ${context.entity_type} matches "${context.query}" with enough confidence ` +
          `(best score ${top.score}, minimum ${MIN_SCORE}).`,
      },
    },
  ];
}

// A runner-up only competes if it clears the confidence floor itself.
// "наушники" put Wireless Earbuds Pro (0.645) ahead of Single (0.599) - a
// music track sitting barely above the 0.55 noise level. Treating that as a
// tie would send the agent asking about a candidate nobody meant. Compare
// this to "толстовки", where Clothing (0.649) is the genuine parent category
// of Hoodies (0.685) and the question is worth asking.
const runnerUpCompetes = runnerUp !== null && runnerUp.score >= MIN_SCORE;

if (runnerUpCompetes && margin !== null && margin < MIN_MARGIN) {
  return [
    {
      json: {
        ...base,
        status: 'ambiguous',
        match: null,
        candidates,
        margin,
        message:
          `Several ${context.entity_type} entries match "${context.query}" closely. ` +
          `Ask the user which one is meant before acting.`,
      },
    },
  ];
}

return [
  {
    json: {
      ...base,
      status: 'resolved',
      match: top,
      candidates,
      margin,
      message: `Resolved "${context.query}" to ${context.entity_type} ${top.entity_id} (${top.name}).`,
    },
  },
];

// Terminal node for the rejected-arguments branch.
//
// The validator refused the call, so no embedding was requested and no search
// was run. Returning the verdict in the same shape as classify-result means the
// agent parses one response format regardless of which branch executed.

const verdict = $input.first().json ?? {};

return [
  {
    json: {
      query: null,
      entity_type: null,
      status: verdict.status ?? 'invalid_input',
      match: null,
      candidates: [],
      errors: verdict.errors ?? [],
      message: verdict.message ?? 'Invalid tool arguments.',
    },
  },
];
